 ]}),
]);
const dump = (n: string, s: any) => {
 console.log("════ " + n + " ════");
 console.log(s.sources.slice(0, 12).map(x => `- [${x.title ?? "?"}](${x.url})\n ${(x.snippet ?? "").slice(0, 175)}`).join("\n"));
